import React, { useState, useEffect } from 'react';
import { loadStripe } from '@stripe/stripe-js';
import { Elements, CardElement, useStripe, useElements } from '@stripe/react-stripe-js';
import Modal from 'react-modal';

const stripePromise = loadStripe('pk_test_YOUR_PUBLIC_KEY'); // Use your Stripe public key

export default function VoiceBookingRecorder() {
  const [clientSecret, setClientSecret] = useState(null);
  const [loading, setLoading] = useState(false);
  const [showModal, setShowModal] = useState(false); // State for modal visibility

  const [name, setName] = useState('');
  const [email, setEmail] = useState('');

  const stripe = useStripe();
  const elements = useElements();

  // Create PaymentIntent when the component is mounted
  useEffect(() => {
    const createPaymentIntent = async () => {
      const res = await fetch('/create-payment-intent', { method: 'POST' });
      const { clientSecret } = await res.json();
      setClientSecret(clientSecret);
    };

    createPaymentIntent();
  }, []);

  const handlePaymentSubmit = async (event) => {
    event.preventDefault();

    if (!stripe || !elements || !clientSecret) {
      return;
    }

    setLoading(true);

    const { error, paymentIntent } = await stripe.confirmCardPayment(clientSecret, {
      payment_method: {
        card: elements.getElement(CardElement),
        billing_details: { name, email }, // Pass name and email along with payment
      },
    });

    setLoading(false);

    if (error) {
      console.error('Payment failed:', error.message);
    } else if (paymentIntent.status === 'succeeded') {
      console.log('Payment successful!');
      // Finalize booking or confirm order here
    }
  };

  return (
    <div>
      <button onClick={() => setShowModal(true)}>Proceed to Payment</button>

      <Modal isOpen={showModal} onRequestClose={() => setShowModal(false)}>
        <h2>Enter Payment Details</h2>
        {clientSecret && (
          <Elements stripe={stripePromise}>
            <div className="card-form-container">
              <form onSubmit={handlePaymentSubmit}>
                <div className="form-group">
                  <label htmlFor="name">Name</label>
                  <input
                    type="text"
                    id="name"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    required
                    placeholder="Your Name"
                  />
                </div>

                <div className="form-group">
                  <label htmlFor="email">Email</label>
                  <input
                    type="email"
                    id="email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                    placeholder="Your Email"
                  />
                </div>

                <div className="card-element">
                  <CardElement />
                </div>

                <button type="submit" disabled={!stripe || loading}>
                  {loading ? 'Processing...' : 'Confirm Payment'}
                </button>
              </form>
            </div>
          </Elements>
        )}
      </Modal>
    </div>
  );
}
